<template>
  <div class="page works-page">
    <header class="page-heading"><div><span class="eyebrow">OUTCOME LIBRARY</span><h1>成果与作品</h1><p>把 Run 的 Artifact 变成可持续改进、可协作、可发布和可撤销分享的真实成果。</p></div><div class="heading-actions"><button class="secondary-button" @click="showCreate = !showCreate">从 Artifact 创建</button><button class="secondary-button" @click="load">刷新</button></div></header>
    <div v-if="error" class="notice error-notice">{{ error }}</div>
    <section v-if="showCreate" class="panel create-work"><div class="section-title"><div><span class="eyebrow">ARTIFACT → WORK</span><h2>保存为作品</h2></div><button class="primary-button" :disabled="saving" @click="create">创建版本 1</button></div><div class="form-grid"><label><span>Run ID</span><input v-model="createForm.run_id" /></label><label><span>Artifact ID</span><input v-model="createForm.artifact_id" /></label><label><span>标题</span><input v-model="createForm.title" /></label><label><span>数据分级</span><select v-model="createForm.data_classification"><option value="internal">Internal</option><option value="public">Public</option><option value="confidential">Confidential</option><option value="restricted">Restricted</option></select></label><label class="wide"><span>作品说明</span><textarea v-model="createForm.description" rows="3" /></label></div></section>

    <div class="works-grid">
      <aside class="panel work-list"><div class="panel-heading"><div><span class="eyebrow">LIBRARY</span><h2>我的作品</h2></div><strong>{{ works.length }}</strong></div><button v-for="item in works" :key="item.work_id" :class="{active:selected?.work_id===item.work_id}" @click="select(item)"><div><strong>{{ item.title }}</strong><span class="status-badge" :class="item.status">{{ item.status }}</span></div><small>v{{ item.current_version }} / published {{ item.published_version || '—' }}</small><p>{{ item.visibility }} · {{ item.data_classification }}</p></button><div v-if="!works.length" class="empty-state compact">Run 完成后，可从产物页形成作品</div></aside>
      <main v-if="selected" class="work-detail">
        <section class="panel work-hero"><div><span class="eyebrow">{{ selected.work_id }}</span><h2>{{ selected.title }}</h2><p>{{ selected.description || '暂无说明' }}</p></div><div class="work-state"><span class="status-badge" :class="selected.status">{{ selected.status }}</span><strong>v{{ selected.current_version }}</strong></div></section>
        <section class="panel work-section"><div class="section-title"><div><span class="eyebrow">PUBLISH</span><h2>发布控制</h2></div><button class="primary-button" :disabled="saving || selected.status==='archived'" @click="publish">发布当前版本</button></div><div class="form-grid three"><label><span>可见性</span><select v-model="publishForm.visibility"><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></label><label><span>数据分级</span><select v-model="publishForm.data_classification"><option value="public">Public</option><option value="internal">Internal</option><option value="confidential">Confidential</option><option value="restricted">Restricted</option></select></label><label><span>公开地址</span><div class="copy-field"><input :value="publicUrl" readonly /><button @click="copy(publicUrl)">复制</button></div></label></div><button v-if="selected.status!=='archived'" class="text-danger" @click="archive">归档作品</button></section>
        <section class="panel work-section"><div class="section-title"><div><span class="eyebrow">NEW VERSION</span><h2>从新 Artifact 迭代</h2></div><button class="secondary-button" :disabled="saving || selected.status==='archived'" @click="addVersion">创建草稿版本</button></div><div class="form-grid three"><label><span>Run ID</span><input v-model="versionForm.run_id" /></label><label><span>Artifact ID</span><input v-model="versionForm.artifact_id" /></label><label><span>改动说明</span><input v-model="versionForm.change_note" /></label></div><pre v-if="selected.version">{{ preview(selected.version.content) }}</pre></section>
        <section class="panel work-section handoff-section"><div class="section-title"><div><span class="eyebrow">CONTINUE WITH AN APP</span><h2>用此成果继续</h2><p>只显示已安装、已激活并明确声明可消费当前成果版本的 App。</p></div><button class="primary-button" :disabled="saving || !handoffForm.installation_id || !handoffForm.consumer_id || !handoffForm.purpose || selected.status==='archived'" @click="handoff">交给 App 使用</button></div><div v-if="consumers.length" class="form-grid three"><label><span>目标 App</span><select v-model="handoffForm.target" @change="chooseConsumer"><option value="">选择 App</option><option v-for="item in consumers" :key="`${item.installation_id}:${item.consumer_id}`" :value="consumerTarget(item)">{{ item.app_name }} · {{ item.name }}</option></select></label><label><span>用途</span><select v-model="handoffForm.purpose" :disabled="!selectedConsumer"><option value="">选择用途</option><option v-for="item in selectedConsumer?.purposes || []" :key="item" :value="item">{{ item }}</option></select></label><label><span>冻结版本</span><input :value="`v${selected.current_version} · ${selected.version?.content_sha256?.slice(0,12) || '—'}`" readonly /></label></div><div v-else class="empty-state compact"><strong>暂无可协作 App</strong><p>安装并激活声明 Work Consumer 的 App 后，它才会出现在这里。</p></div><article v-for="item in handoffs" :key="item.handoff_id" class="handoff-row"><div><strong>{{ item.app_id }} · {{ item.purpose }}</strong><small>v{{ item.work_version }} · {{ item.status }} · {{ format(item.created_at) }}</small></div><button v-if="['authorized','accepted','executing'].includes(item.status)" class="text-danger" :disabled="saving" @click="cancelHandoff(item.handoff_id)">撤销交接</button></article></section>
        <section class="work-lower">
          <div class="panel work-section"><div class="section-title"><div><span class="eyebrow">SHARING</span><h2>可撤销分享</h2></div><button class="primary-button" :disabled="saving || !selected.published_version" @click="share">生成链接</button></div><div class="inline-form"><select v-model="shareForm.permission"><option value="view">View</option><option value="download">Download</option></select><input v-model.number="shareForm.expires_in_seconds" type="number" min="60" placeholder="有效秒数" /></div><div v-if="issuedToken" class="issued-token"><strong>链接仅显示一次</strong><div class="copy-field"><input :value="issuedToken" readonly /><button @click="copy(issuedToken)">复制</button></div></div><article v-for="item in shares" :key="item.share_id"><div><strong>v{{ item.version }} · {{ item.permission }}</strong><small>{{ item.status }} · {{ format(item.expires_at) }}</small></div><button v-if="item.status==='active'" @click="revokeShare(item.share_id)">撤销</button></article></div>
          <div class="panel work-section"><div class="section-title"><div><span class="eyebrow">COLLABORATION</span><h2>协作者</h2></div><button class="secondary-button" :disabled="!collaborator.user_id" @click="grant">添加</button></div><div class="inline-form"><input v-model="collaborator.user_id" placeholder="user_id" /><select v-model="collaborator.role"><option value="viewer">Viewer</option><option value="editor">Editor</option></select></div><article v-for="item in collaborators" :key="item.user_id"><div><strong>{{ item.user_id }}</strong><small>{{ item.role }}</small></div><button @click="removeCollaborator(item.user_id)">移除</button></article></div>
        </section>
        <section class="panel work-section"><div class="section-title"><div><span class="eyebrow">AUDIT</span><h2>访问与治理审计</h2></div><strong>{{ audit.length }}</strong></div><div class="audit-list"><article v-for="item in audit" :key="String(item.audit_id)"><code>{{ item.event_type }}</code><span>{{ item.actor_id }}</span><small>{{ format(String(item.created_at || '')) }}</small></article></div></section>
      </main><div v-else class="panel empty-state"><span>◆</span><strong>选择一项作品</strong><p>查看版本、发布、分享、协作者与访问审计。</p></div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useMessage } from 'naive-ui'
import { cancelWorkHandoff, createWork, createWorkHandoff, createWorkShare, createWorkVersion, getWork, grantWorkCollaborator, listWorkAudit, listWorkCollaborators, listWorkConsumers, listWorkHandoffs, listWorkShares, listWorks, revokeWorkCollaborator, revokeWorkShare, updateWork, type Work, type WorkConsumer, type WorkHandoff, type WorkShare } from '../api/works'
const route=useRoute(); const toast=useMessage(); const works=ref<Work[]>([]); const selected=ref<Work|null>(null); const shares=ref<WorkShare[]>([]); const consumers=ref<WorkConsumer[]>([]); const handoffs=ref<WorkHandoff[]>([]); const audit=ref<Array<Record<string,unknown>>>([]); const collaborators=ref<Array<Record<string,string>>>([]); const saving=ref(false); const error=ref(''); const showCreate=ref(false); const issuedToken=ref('')
const createForm=reactive({run_id:'',artifact_id:'',title:'',description:'',data_classification:'internal'}); const versionForm=reactive({run_id:'',artifact_id:'',change_note:''}); const publishForm=reactive({visibility:'private',data_classification:'internal'}); const shareForm=reactive({permission:'view',expires_in_seconds:86400}); const collaborator=reactive({user_id:'',role:'viewer'}); const handoffForm=reactive({target:'',installation_id:'',consumer_id:'',purpose:''})
const publicUrl=ref('')
const selectedConsumer=computed(()=>consumers.value.find(item=>item.installation_id===handoffForm.installation_id&&item.consumer_id===handoffForm.consumer_id))
function preview(value:unknown){const text=typeof value==='string'?value:JSON.stringify(value,null,2);return text?.slice(0,5000)||'无内嵌内容'} function format(value?:string|null){return value?new Date(value).toLocaleString('zh-CN'):'永久'}
async function copy(value:string){if(!value)return;await navigator.clipboard.writeText(value);toast.success('已复制')}
async function load(){error.value='';try{works.value=await listWorks();if(selected.value){const current=works.value.find(item=>item.work_id===selected.value?.work_id);if(current)await select(current)}}catch(cause){error.value=cause instanceof Error?cause.message:'读取作品失败'}}
async function select(value:Work){try{selected.value=await getWork(value.work_id);Object.assign(publishForm,{visibility:selected.value.visibility,data_classification:selected.value.data_classification});publicUrl.value=`${window.location.origin}/v1/public/works/${selected.value.public_slug}`;[shares.value,consumers.value,handoffs.value,audit.value,collaborators.value]=await Promise.all([listWorkShares(value.work_id),listWorkConsumers(value.work_id),listWorkHandoffs(value.work_id),listWorkAudit(value.work_id),listWorkCollaborators(value.work_id)]);Object.assign(handoffForm,{target:'',installation_id:'',consumer_id:'',purpose:''});issuedToken.value=''}catch(cause){toast.error(cause instanceof Error?cause.message:'读取作品详情失败')}}
async function act(task:()=>Promise<void>){saving.value=true;try{await task()}catch(cause){toast.error(cause instanceof Error?cause.message:'操作失败')}finally{saving.value=false}}
function create(){void act(async()=>{const item=await createWork({...createForm});toast.success('作品已创建');showCreate.value=false;await load();await select(item)})}
function publish(){if(!selected.value)return;void act(async()=>{selected.value=await updateWork(selected.value!.work_id,{status:'published',...publishForm});toast.success('当前版本已发布');await load()})}
function archive(){if(!selected.value||!confirm('归档后不能重新打开，确认继续？'))return;void act(async()=>{selected.value=await updateWork(selected.value!.work_id,{status:'archived'});toast.success('作品已归档');await load()})}
function addVersion(){if(!selected.value)return;void act(async()=>{selected.value=await createWorkVersion(selected.value!.work_id,{...versionForm});toast.success('新草稿版本已创建，上一发布版本仍可访问');await load()})}
function consumerTarget(item:WorkConsumer){return JSON.stringify([item.installation_id,item.consumer_id])}
function chooseConsumer(){try{const parsed=JSON.parse(handoffForm.target);if(!Array.isArray(parsed)||parsed.length!==2)throw new Error('invalid target');handoffForm.installation_id=String(parsed[0]||'');handoffForm.consumer_id=String(parsed[1]||'')}catch{handoffForm.installation_id='';handoffForm.consumer_id=''}handoffForm.purpose=selectedConsumer.value?.purposes[0]||''}
function handoff(){if(!selected.value)return;void act(async()=>{await createWorkHandoff(selected.value!.work_id,{installation_id:handoffForm.installation_id,consumer_id:handoffForm.consumer_id,purpose:handoffForm.purpose,work_version:selected.value!.current_version});toast.success('成果已交给 App，等待其接收并回写结果');await select(selected.value!)})}
function cancelHandoff(id:string){if(!confirm('撤销后 App 将不能继续读取这个成果版本，确认继续？'))return;void act(async()=>{await cancelWorkHandoff(id);toast.success('交接已撤销');if(selected.value)await select(selected.value)})}
function share(){if(!selected.value)return;void act(async()=>{const item=await createWorkShare(selected.value!.work_id,{permission:shareForm.permission,expires_in_seconds:Number(shareForm.expires_in_seconds)||null});issuedToken.value=`${window.location.origin}${item.path}`;shares.value=await listWorkShares(selected.value!.work_id);toast.success('分享链接已生成，请立即保存')})}
function revokeShare(id:string){if(!selected.value)return;void act(async()=>{await revokeWorkShare(selected.value!.work_id,id);shares.value=await listWorkShares(selected.value!.work_id);audit.value=await listWorkAudit(selected.value!.work_id);toast.success('分享已撤销')})}
function grant(){if(!selected.value)return;void act(async()=>{await grantWorkCollaborator(selected.value!.work_id,collaborator.user_id,collaborator.role as 'viewer'|'editor');collaborators.value=await listWorkCollaborators(selected.value!.work_id);collaborator.user_id='';toast.success('协作者已更新')})}
function removeCollaborator(userId:string){if(!selected.value)return;void act(async()=>{await revokeWorkCollaborator(selected.value!.work_id,userId);collaborators.value=await listWorkCollaborators(selected.value!.work_id)})}
onMounted(async()=>{createForm.run_id=String(route.query.run||'');createForm.artifact_id=String(route.query.artifact||'');showCreate.value=Boolean(createForm.run_id&&createForm.artifact_id);await load()})
</script>

<style scoped>
.create-work,.work-section{padding:20px;margin-bottom:14px}.section-title,.work-hero,.work-list button>div,.work-section article,.copy-field,.inline-form{display:flex;align-items:center;justify-content:space-between;gap:9px}.section-title h2,.work-hero h2{margin:5px 0 0;color:var(--text-strong);font-size:18px}.section-title p{margin:5px 0 0;color:var(--text-muted);font-size:11px}.works-grid{display:grid;grid-template-columns:260px minmax(0,1fr);gap:14px;align-items:start}.work-list{overflow:hidden}.work-list>button{display:grid;gap:5px;width:100%;padding:13px 15px;border:0;border-top:1px solid var(--border);color:var(--text);background:transparent;text-align:left;cursor:pointer}.work-list>button:hover,.work-list>button.active{background:var(--surface-hover)}.work-list small,.work-list p{margin:0;color:var(--text-muted);font:9px var(--font-mono)}.work-detail{min-width:0}.work-hero{padding:22px}.work-hero p{margin:8px 0 0;color:var(--text-muted)}.work-state{display:grid;gap:8px;text-align:right}.work-state strong{font:18px var(--font-mono)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.form-grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.form-grid .wide{grid-column:1/-1}.form-grid label{display:grid;gap:5px;color:var(--text-muted);font-size:10px}.form-grid input,.form-grid textarea,.form-grid select,.inline-form input,.inline-form select,.copy-field input{box-sizing:border-box;width:100%;padding:9px;color:var(--text);background:var(--input);border:1px solid var(--border);border-radius:8px}.copy-field button,.work-section article>button{padding:7px;border:0;color:var(--accent);background:transparent;cursor:pointer}.text-danger{margin-top:14px;padding:0;border:0;color:var(--danger);background:transparent;cursor:pointer}.work-section pre{max-height:300px;overflow:auto;padding:12px;border-radius:9px;color:var(--text);background:var(--input);font:10px/1.5 var(--font-mono);white-space:pre-wrap}.work-lower{display:grid;grid-template-columns:1fr 1fr;gap:14px}.work-lower .work-section{margin:0}.inline-form{margin:12px 0}.work-section article{padding:9px 0;border-top:1px solid var(--border)}.work-section article div{display:grid;gap:3px}.work-section article small{color:var(--text-muted);font-size:9px}.handoff-section .empty-state{margin-top:12px;padding:14px}.handoff-row{margin-top:10px}.issued-token{display:grid;gap:7px;margin:10px 0;padding:10px;border:1px solid var(--warning);border-radius:9px;background:var(--warning-subtle)}.issued-token strong{font-size:10px}.audit-list{max-height:260px;overflow:auto}.audit-list article{display:grid;grid-template-columns:180px 1fr auto}.audit-list code{color:var(--accent)}@media(max-width:900px){.works-grid,.work-lower{grid-template-columns:1fr}.form-grid.three{grid-template-columns:1fr}.work-list{max-height:260px;overflow:auto}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.work-hero{align-items:flex-start;flex-direction:column}}
</style>
